Plan:
1. Scan sheet **A** column **P** for the first `Yes`/`NA`, then take the closest `100` above it in column **L** and its date from column **F** (fallback to **F3** if no `Yes`/`NA`).
2. Match **A!F1** against sheet **B** column **C** to find the target row (Silver → row 4).
3. Write the resulting date as a real datetime into **B!F4** and set sheet **A** active.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

wsA = vals["A"]
wsB = vals["B"]

def is_yes_na(v):
    return v is not None and str(v).strip().lower() in {"yes", "na"}

def is_100(v):
    if v is None:
        return False
    try:
        return float(v) == 100.0
    except (TypeError, ValueError):
        return False

def to_datetime(v):
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)):
        return (datetime(1899, 12, 30) + timedelta(days=float(v))).replace(
            hour=0, minute=0, second=0, microsecond=0
        )
    if isinstance(v, str):
        s = v.strip()
        for fmt in (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
            "%d/%m/%Y %H:%M:%S",
            "%d/%m/%Y",
        ):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
    return v

first_row = None
for r in range(1, wsA.max_row + 1):
    if is_yes_na(wsA.cell(row=r, column=16).value):  # column P
        first_row = r
        break

target_date = None
last_100_row = None

if first_row is None:
    target_date = wsA.cell(row=3, column=6).value  # A!F3
else:
    for r in range(1, first_row):
        if is_100(wsA.cell(row=r, column=12).value):  # column L
            last_100_row = r

    if last_100_row is not None:
        target_date = wsA.cell(row=last_100_row, column=6).value  # column F
    else:
        target_date = wsA.cell(row=3, column=6).value  # safe fallback

target_date = to_datetime(target_date)

f1 = wsA.cell(row=1, column=6).value  # A!F1
f1_key = str(f1).strip() if f1 is not None else ""

b_row = 4  # default answer cell row
for r in range(1, wsB.max_row + 1):
    v = wsB.cell(row=r, column=3).value  # column C
    if v is not None and str(v).strip() == f1_key:
        b_row = r
        break

outB = wb["B"]
outB.cell(row=b_row, column=6).value = target_date  # column F

wb.active = 0  # keep sheet A active
wb.save(OUT)

print("first_row:", first_row)
print("last_100_row:", last_100_row)
print("b_row:", b_row)
print("target_date:", target_date)
```

